SELECT s.schedule_id, s.schedule_code, s.classroom_id, s.lesson_location, s.course_year, s.term_name, s.period_name,
       s.time_slot, s.start_time, s.end_time, s.start_date, s.end_date, s.class_pattern,
       s.grade_name, s.subject_name, s.teacher_name, s.teacher_id,
       s.class_type, s.class_mode, s.enrolled_count, s.enroll_limit, s.recruit_status, s.course_class_name,
       s.status, s.del_flag, s.create_by, s.create_time, s.update_by, s.update_time, s.remark
FROM edu_course_schedule s
LEFT JOIN edu_classroom c ON c.classroom_id = s.classroom_id

    s.del_flag = '0' AND s.status = '0'
    and s.teacher_id = #{params.teacherUserId}
     and s.course_year = #{courseYear}
     and s.term_name   = #{termName}
     and s.period_name = #{periodName}
     and s.classroom_id = #{classroomId}
     and s.time_slot    = #{timeSlot}
     and s.grade_name   = #{gradeName}
     and s.subject_name = #{subjectName}

    and s.teacher_id = #{params.teacherUserId}
     and s.class_type   = #{classType}

     and c.campus_name = #{remark}

ORDER BY s.course_year, s.term_name, s.period_name, c.campus_name, c.classroom_id, s.time_slot

