UPDATE edu_course_schedule
SET classroom_id = CASE classroom_id
        WHEN #{classroomIdA} THEN #{classroomIdB}
        WHEN #{classroomIdB} THEN #{classroomIdA}
    END,
    update_time = NOW()
    , update_by = #{updateBy}
WHERE del_flag = '0'
  AND classroom_id IN (#{classroomIdA}, #{classroomIdB})
  AND course_year = #{courseYear}
  AND term_name = #{termName}
  AND period_name = #{periodName}
